# -*- coding: utf-8 -*-
"""目录页修复 —— Mac 与 Windows 共用。

带点线的目录页（"标题 ……… 页码"）在普通翻译流程里会被当成流水正文处理：
分级缩进丢失、页码被塞进正文行内、条目跨行断开甚至丢条，整页糊成一团。

这里在翻译完成后做一次后处理：
    从**原文页**抽出目录条目(缩进层级 / 编号 / 标题 / 页码)
    → 把所有标题拼成**一次**翻译请求(不逐条发，速度基本无影响)
    → 按原来的缩进、点线、右对齐页码重排到译文页上

检测很保守（要求整页多数行都是"有点线且行尾是页码"的条目），普通正文页不会误命中；
任何一页处理失败都只跳过该页、保持原样，不影响其余翻译结果。
"""
import re
import fitz

_ONLY_DOTS = re.compile(r'^[.·…\s]+$')
_ONLY_NUM = re.compile(r'^\d{1,4}$')
_NUMBERING = re.compile(r'^((?:\d+\.)*\d+)\s+(.*)$')   # 条目开头的 3 / 3.1 / 3.1.1


def _is_cjk(ch):
    return '⺀' <= ch <= '鿿' or '＀' <= ch <= '￯'


def extract_toc_entries(page):
    """抽出一页里的目录条目。标题、点线、页码在 PDF 里常是彼此独立的 line 对象，
    这里先按 y 中心把它们聚成"视觉行"，再判定/组装。"""
    d = page.get_text("dict")
    frags = []
    for blk in d.get("blocks", []):
        for ln in blk.get("lines", []):
            spans = ln.get("spans", [])
            if not spans:
                continue
            txt = "".join(s["text"] for s in spans).strip()
            if not txt:
                continue
            b = ln["bbox"]
            frags.append({"x0": b[0], "x1": b[2], "y0": b[1], "y1": b[3],
                          "yc": (b[1] + b[3]) / 2,
                          "size": max(s["size"] for s in spans), "text": txt})
    if not frags:
        return []
    frags.sort(key=lambda f: (f["yc"], f["x0"]))
    rows, cur = [], [frags[0]]
    for f in frags[1:]:
        if abs(f["yc"] - cur[-1]["yc"]) <= max(cur[-1]["size"], f["size"]) * 0.6:
            cur.append(f)
        else:
            rows.append(cur); cur = [f]
    rows.append(cur)

    entries = []
    for row in rows:
        row.sort(key=lambda f: f["x0"])
        dots = [f for f in row if _ONLY_DOTS.match(f["text"])]
        nums = [f for f in row if _ONLY_NUM.match(f["text"])]
        others = [f for f in row if f not in dots and f not in nums]
        if not dots or not nums or not others:
            continue
        title = " ".join(f["text"] for f in others).strip()
        if len(re.sub(r'[.\s·…]', '', title)) < 2:
            continue
        pg = max(nums, key=lambda f: f["x0"])      # 最右侧的数字才是页码
        entries.append({
            "x0": min(f["x0"] for f in others),
            "y0": min(f["y0"] for f in row),
            "y1": max(f["y1"] for f in row),
            "size": max(f["size"] for f in row),
            "title": title, "page": pg["text"], "page_x1": pg["x1"],
        })
    entries.sort(key=lambda e: e["y0"])
    return entries


def is_toc_page(page, entries):
    """整页是否为目录页：条目够多，且这些条目占了页面文字行的多数
    （一个条目通常由 标题 / 点线 / 页码 三个 line 组成）。"""
    if len(entries) < 5:
        return False
    d = page.get_text("dict")
    rows = sum(len(b.get("lines", [])) for b in d.get("blocks", []))
    return rows > 0 and len(entries) * 3 >= rows * 0.6


def _translate_titles(entries, translator):
    """把条目标题打包成一次请求翻译；拆回条数对不上才逐条兜底。
    条目开头的编号(3.1.1 等)不送去翻译，原样保留，避免被翻译器改写。"""
    heads, bodies = [], []
    for e in entries:
        m = _NUMBERING.match(e["title"])
        heads.append(m.group(1) if m else "")
        bodies.append((m.group(2) if m else e["title"]).strip())
    try:
        zh = translator.translate("\n".join(bodies)) or ""
    except Exception:
        zh = ""
    zh_lines = [l.strip() for l in zh.split("\n")] if zh else []
    if len(zh_lines) != len(bodies):
        zh_lines = []
        for b in bodies:
            try:
                zh_lines.append((translator.translate(b) or b).strip())
            except Exception:
                zh_lines.append(b)
    return heads, zh_lines


def _render_toc(page, entries, heads, zh_lines, font_bytes):
    """按原缩进/点线/右对齐页码，把译好的条目重排到页面上。"""
    top = min(e["y0"] for e in entries) - 3
    bot = max(e["y1"] for e in entries) + 3
    left = min(e["x0"] for e in entries) - 3
    right = max(e["page_x1"] for e in entries) + 3
    page.draw_rect(fitz.Rect(left, top, right, bot), color=None, fill=(1, 1, 1))

    arc = face = None
    if font_bytes:
        try:
            arc = fitz.Archive(); arc.add(font_bytes, "han.ttf")
            face = "@font-face{font-family:han;src:url(han.ttf);}"
        except Exception:
            arc = face = None
    fam = "han" if arc is not None else "sans-serif"
    face = face or ""

    for e, head, zt in zip(entries, heads, zh_lines):
        fs = max(min(e["size"], 12), 7)
        title = (head + "  " + zt).strip() if head else zt
        pg = e["page"]
        pgw = fitz.get_text_length(pg, fontname="tiro", fontsize=fs)
        px = e["page_x1"] - pgw
        page.insert_text((px, e["y1"] - fs * 0.25), pg, fontname="tiro", fontsize=fs)

        box = fitz.Rect(e["x0"], e["y0"] - 1, max(px - 6, e["x0"] + fs), e["y1"] + 2)
        css = (f"{face}* {{font-family:{fam};font-size:{fs:.1f}px;"
               f"line-height:1.05;color:black;white-space:nowrap;}}")
        esc = title.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        try:
            if arc is not None:
                page.insert_htmlbox(box, esc, css=css, archive=arc, scale_low=0)
            else:
                page.insert_htmlbox(box, esc, css=css, scale_low=0)
        except Exception:
            continue

        # 点线：逐字符量宽（中文全角、西文真实字宽），混排标题才不会把起点算偏
        tw = 0.0
        for ch in title:
            tw += fs if _is_cjk(ch) else fitz.get_text_length(ch, fontname="tiro", fontsize=fs)
        ds = min(e["x0"] + tw + 4, px - 10)
        de = px - 4
        if de > ds:
            dw = fitz.get_text_length(".", fontname="tiro", fontsize=fs) or 1
            page.insert_text((ds, e["y1"] - fs * 0.25), "." * max(int((de - ds) / dw), 0),
                             fontname="tiro", fontsize=fs, color=(0.35, 0.35, 0.35))


def fix_toc_pages(src_path, out_path, translator, font_bytes=None,
                  dual=False, pages=None, status_cb=None):
    """修复译文文件里的目录页。返回修好的页数。

    src_path: 原文 PDF（目录条目要从这里抽，译文页上的目录已经乱了抽不出来）
    out_path: 待修复的译文 PDF（mono 或 dual），就地改写
    dual:     out 是 dual 格式（偶数页原文 / 奇数页译文），只修奇数页
    pages:    翻译时选择的页码范围(0-indexed)，用于把译文页映射回原文页
    """
    fixed = 0
    src = out = None
    try:
        src = fitz.open(src_path)
        out = fitz.open(out_path)
        n_out = out.page_count
        for oi in range(n_out):
            if dual and oi % 2 == 0:
                continue                      # dual 偶数页是原文，不动
            k = (oi - 1) // 2 if dual else oi  # 译文页序号
            si = pages[k] if (pages and k < len(pages)) else k
            if si >= src.page_count:
                continue
            try:
                sp = src[si]
                entries = extract_toc_entries(sp)
                if not is_toc_page(sp, entries):
                    continue
                if status_cb:
                    status_cb(f"正在还原目录页排版…（第 {si + 1} 页，{len(entries)} 条）")
                heads, zh_lines = _translate_titles(entries, translator)
                _render_toc(out[oi], entries, heads, zh_lines, font_bytes)
                fixed += 1
            except Exception:
                continue                      # 单页失败不影响其它页
        if fixed:
            import os, tempfile
            fd, tmp = tempfile.mkstemp(suffix=".pdf", dir=os.path.dirname(out_path) or None)
            os.close(fd)
            out.save(tmp, garbage=4, deflate=True)
            out.close(); out = None
            os.replace(tmp, out_path)
    except Exception:
        pass
    finally:
        for d in (src, out):
            if d:
                try: d.close()
                except Exception: pass
    return fixed
